//! Printing the generated files.

mod apis;
mod models;
mod queries;

use crate::config::{Config, Decode};
use crate::ir::Operation;
use crate::types::Types;
use serde_json::Value;

/// The first line of every file swagger-rust regenerates; files starting
/// with it may be overwritten or removed.
pub const GENERATED_MARKER: &str = "// @generated by swagger-rust";

const RUNTIME: &str = include_str!("../../templates/runtime.rs");
const JSON_STRICT: &str = include_str!("../../templates/json_strict.rs");
const JSON_LENIENT: &str = include_str!("../../templates/json_lenient.rs");
const QUERY_CLIENT: &str = include_str!("../../templates/query_client.rs");
const CONFIG: &str = include_str!("../../templates/config.rs");

/// A file to write into the output directory.
pub struct File {
    pub name: &'static str,
    pub content: String,
    /// `false` for `config.rs`: only written when missing.
    pub regenerate: bool,
}

pub struct Context<'a> {
    pub config: &'a Config,
    pub document: &'a Value,
}

impl Context<'_> {
    pub fn lenient(&self) -> bool {
        self.config.decode == Decode::Lenient
    }

    fn title(&self) -> String {
        self.document
            .pointer("/info/title")
            .and_then(Value::as_str)
            .map(str::to_owned)
            .filter(|t| !t.trim().is_empty())
            .unwrap_or_else(|| self.config.module_name())
    }

    fn version(&self) -> Option<String> {
        self.document
            .pointer("/info/version")
            .and_then(Value::as_str)
            .map(str::to_owned)
            .filter(|v| !v.is_empty())
    }

    fn gpui(&self) -> String {
        self.config.gpui_crate.trim_start_matches("::").to_owned()
    }
}

/// Every file of the client.
pub fn render(
    config: &Config,
    document: &Value,
    operations: &[Operation],
    types: &Types,
) -> Vec<File> {
    let cx = Context { config, document };
    let mut files = vec![
        File {
            name: "mod.rs",
            content: module(&cx),
            regenerate: true,
        },
        File {
            name: "config.rs",
            content: config_file(&cx),
            regenerate: false,
        },
        File {
            name: "runtime.rs",
            content: template(RUNTIME),
            regenerate: true,
        },
        File {
            name: "json.rs",
            content: template(if cx.lenient() {
                JSON_LENIENT
            } else {
                JSON_STRICT
            }),
            regenerate: true,
        },
        File {
            name: "models.rs",
            content: models::render(&cx, types),
            regenerate: true,
        },
        File {
            name: "apis.rs",
            content: apis::render(&cx, operations),
            regenerate: true,
        },
    ];
    if config.gpui {
        let timeout = if config.gpui_http_timeout {
            "if let Some(timeout) = timeout {\n            builder = builder.timeout(timeout);\n        }"
        } else {
            "let _ = timeout; // `gpuiHttpTimeout` is off"
        };
        let query_client = QUERY_CLIENT
            .replace("__GPUI__", &cx.gpui())
            .replace("__TIMEOUT__", timeout);
        files.push(File {
            name: "query_client.rs",
            content: template(&query_client),
            regenerate: true,
        });
        files.push(File {
            name: "queries.rs",
            content: queries::render(&cx, operations, types),
            regenerate: true,
        });
    }
    files
}

fn generated_header() -> String {
    format!(
        "{GENERATED_MARKER} {}. Do not edit: run `swagger-rust` to regenerate.\n",
        env!("CARGO_PKG_VERSION")
    )
}

fn template(source: &str) -> String {
    format!("{}{source}", generated_header())
}

fn module(cx: &Context) -> String {
    let mut out = generated_header();
    let title = cx.title();
    let version = cx.version().map(|v| format!(" {v}")).unwrap_or_default();
    out.push_str(&doc_comment(
        &format!("Client for {title}{version}, generated by swagger-rust."),
        "",
        true,
    ));
    out.push_str("//!\n");
    out.push_str("//! * [`apis`]: an async function per endpoint; pass it a [`Transport`].\n");
    out.push_str("//! * [`models`]: the request and response types.\n");
    out.push_str(
        "//! * [`config`]: base url, headers, response envelope. Generated once, yours to edit.\n",
    );
    out.push_str("//! * [`runtime`]: requests, [`ApiError`], encoding.\n");
    if cx.config.gpui {
        out.push_str(
            "//! * [`queries`]: the GET endpoints as cached GPUI queries ([`query_client`]).\n",
        );
    }
    out.push_str(
        "//!\n//! Every file but `config.rs` is rewritten when the client is regenerated.\n",
    );
    // API titles ("OpenAPI 3.1 Petstore") read as unbackticked code to clippy.
    out.push_str("#![allow(clippy::doc_markdown)]\n\n");
    let mut modules = vec!["apis", "config", "json", "models", "runtime"];
    if cx.config.gpui {
        modules.extend(["queries", "query_client"]);
    }
    modules.sort_unstable();
    for module in modules {
        out.push_str(&format!("pub mod {module};\n"));
    }
    out.push_str("\npub use runtime::{ApiError, Transport};\n");
    out
}

fn config_file(cx: &Context) -> String {
    let base_url = cx
        .config
        .base_url
        .clone()
        .unwrap_or_else(|| server_url(cx.document));
    CONFIG
        .replace("__TITLE__", &cx.title().replace('\n', " "))
        .replace("__BASE_URL__", &base_url.replace('"', "\\\""))
}

/// The first server url, its `{variables}` filled with their defaults.
fn server_url(document: &Value) -> String {
    let Some(server) = document.pointer("/servers/0") else {
        return String::new();
    };
    let mut url = server
        .get("url")
        .and_then(Value::as_str)
        .unwrap_or_default()
        .to_owned();
    if let Some(Value::Object(variables)) = server.get("variables") {
        for (name, variable) in variables {
            if let Some(default) = variable.get("default").and_then(Value::as_str) {
                url = url.replace(&format!("{{{name}}}"), default);
            }
        }
    }
    if url == "/" {
        String::new()
    } else {
        url
    }
}

/// `///` (or `//!`) lines for `text`. Lines are unindented, so nothing
/// becomes an indented code block, and code fences that rustdoc would run
/// as Rust doctests are marked `text`.
pub fn doc_comment(text: &str, indent: &str, inner: bool) -> String {
    let prefix = if inner { "//!" } else { "///" };
    let normalized = text.replace("\r\n", "\n").replace('\r', "\n");
    let lines: Vec<&str> = normalized.lines().map(str::trim).collect();
    let start = lines
        .iter()
        .position(|l| !l.is_empty())
        .unwrap_or(lines.len());
    let end = lines
        .iter()
        .rposition(|l| !l.is_empty())
        .map(|i| i + 1)
        .unwrap_or(start);
    let mut out = String::new();
    let mut in_fence = false;
    for line in &lines[start..end] {
        let mut line = (*line).to_owned();
        if let Some(info) = line.strip_prefix("```") {
            if !in_fence {
                let first = info.split([',', ' ']).next().unwrap_or("").trim();
                let rust_like = matches!(
                    first,
                    "" | "rust"
                        | "should_panic"
                        | "no_run"
                        | "ignore"
                        | "compile_fail"
                        | "edition2015"
                        | "edition2018"
                        | "edition2021"
                        | "edition2024"
                );
                if rust_like {
                    line = "```text".to_owned();
                }
            }
            in_fence = !in_fence;
        }
        if line.is_empty() {
            out.push_str(&format!("{indent}{prefix}\n"));
        } else {
            out.push_str(&format!("{indent}{prefix} {line}\n"));
        }
    }
    if in_fence {
        out.push_str(&format!("{indent}{prefix} ```\n"));
    }
    out
}

/// A Rust string literal.
pub fn string_literal(text: &str) -> String {
    format!("{text:?}")
}

/// The `#![allow]` of generated modules.
const ALLOW: &str = "#![allow(dead_code, unused_imports, deprecated, unreachable_patterns, non_camel_case_types, clippy::all, clippy::pedantic, clippy::nursery, rustdoc::bare_urls, rustdoc::broken_intra_doc_links, rustdoc::invalid_html_tags, rustdoc::invalid_rust_codeblocks)]\n";

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn doc_comments_are_safe_for_rustdoc() {
        let doc = doc_comment(
            "  Title\n\n      indented\n```\nlet x = 1;\n```\n```json\n{}\n```",
            "    ",
            false,
        );
        assert_eq!(
            doc,
            "    /// Title\n    ///\n    /// indented\n    /// ```text\n    /// let x = 1;\n    /// ```\n    /// ```json\n    /// {}\n    /// ```\n"
        );
        assert_eq!(
            doc_comment("open\n```", "", false),
            "/// open\n/// ```text\n/// ```\n"
        );
    }
}
